import { createHash, randomUUID } from "node:crypto";
import type { PoolClient } from "pg";
import type {
  BookViewKey,
  CardArchiveImpactItem,
  CardArchivePreview,
  CardArchiveReceipt,
  CardSummary,
  MaterialFilterCondition,
  MaterialFilterNode,
  MaterialGroup,
  MaterialManagementWorkspace,
  MaterialQueryPage,
  MaterialSortRule,
  MaterialTag,
  SmartMaterialView,
} from "../../../common/contracts";
import { NewDesignError, assertFound } from "../../domain/errors";
import { stableHash } from "../aiContracts/integrity";
import { getNewDesignPool } from "../runtime";

type ScopeInput={bookId?:string;spaceId?:string};
type Scope={spaceId:string;bookId:string|null};
type ActorInput={actor?:string;visibility?:"space"|"private"};
type TagInput=ActorInput&{key:string;name:string;aliases:string[];color?:string|null;metadata:Record<string,unknown>;dimensionId?:string;parentId?:string|null;sortOrder?:number;idempotencyKey:string};
type TagRevisionInput=Omit<TagInput,"key">&{expectedRevision:number};
type GroupInput=ActorInput&{key:string;name:string;parentId?:string|null;sortOrder:number;idempotencyKey:string};
type GroupRevisionInput=ActorInput&{name:string;parentId?:string|null;sortOrder:number;expectedRevision:number;idempotencyKey:string};
type SmartViewInput=ActorInput&{key:string;name:string;description:string;baseViewKey?:BookViewKey|null;filter:MaterialFilterNode;sort:MaterialSortRule[];grouping:{field?:string};displayColumns:string[];layout:{mode:"list"|"table";[key:string]:unknown};idempotencyKey:string};
type SmartViewRevisionInput=Omit<SmartViewInput,"key"|"baseViewKey">&{expectedRevision:number};

const ACTOR="user";
function asDate(value:unknown):string{return value instanceof Date?value.toISOString():new Date(String(value)).toISOString();}
function asArray<T>(value:unknown):T[]{return Array.isArray(value)?value as T[]:[];}

async function resolveScope(client:PoolClient,input:ScopeInput):Promise<Scope>{
  if(Boolean(input.bookId)===Boolean(input.spaceId))throw new NewDesignError("必须且只能指定书籍或公共资源空间。",422);
  if(input.bookId){const book=assertFound((await client.query("SELECT id,space_id,status FROM new_design.books WHERE id=$1",[input.bookId])).rows[0],"书籍不存在。");if(book.status!=="active")throw new NewDesignError("书籍已归档，不能修改资料组织。",409);return{bookId:String(book.id),spaceId:String(book.space_id)};}
  const space=assertFound((await client.query("SELECT id FROM new_design.card_spaces WHERE id=$1 AND NOT EXISTS(SELECT 1 FROM new_design.books WHERE space_id=card_spaces.id)",[input.spaceId])).rows[0],"公共资源空间不存在，或该空间属于一本书。");return{bookId:null,spaceId:String(space.id)};
}

function mapTag(row:Record<string,unknown>):MaterialTag{return{id:String(row.id),spaceId:String(row.space_id),key:String(row.tag_key),name:String(row.name),aliases:asArray<string>(row.aliases),color:row.color?String(row.color):null,metadata:(row.metadata??{}) as Record<string,unknown>,dimensionId:row.dimension_id?String(row.dimension_id):null,parentId:row.parent_id?String(row.parent_id):null,sortOrder:Number(row.sort_order??1000),path:asArray<unknown>(row.path_node_ids).map((id,index)=>({id:String(id),name:String(asArray<unknown>(row.path_names)[index]??row.name)})),childCount:Number(row.child_count??0),status:row.status as MaterialTag["status"],revision:Number(row.revision),currentVersionId:String(row.current_version_id),visibility:row.visibility as MaterialTag["visibility"],memberCount:Number(row.member_count??0),updatedAt:asDate(row.updated_at)};}
function mapGroup(row:Record<string,unknown>):MaterialGroup{return{id:String(row.id),spaceId:String(row.space_id),bookId:row.book_id?String(row.book_id):null,key:String(row.group_key),name:String(row.name),parentId:row.parent_id?String(row.parent_id):null,sortOrder:Number(row.sort_order),status:row.status as MaterialGroup["status"],revision:Number(row.revision),currentVersionId:String(row.current_version_id),visibility:row.visibility as MaterialGroup["visibility"],memberCount:Number(row.member_count??0),updatedAt:asDate(row.updated_at)};}
function mapView(row:Record<string,unknown>):SmartMaterialView{return{id:String(row.id),spaceId:String(row.space_id),bookId:row.book_id?String(row.book_id):null,key:String(row.view_key),baseViewKey:(row.base_view_key??null) as BookViewKey|null,name:String(row.name),description:String(row.description??""),filter:row.filter_ast as MaterialFilterNode,sort:asArray<MaterialSortRule>(row.sort_config),grouping:(row.grouping??{}) as {field?:string},displayColumns:asArray<string>(row.display_columns),layout:(row.layout??{mode:"list"}) as SmartMaterialView["layout"],status:row.status as SmartMaterialView["status"],revision:Number(row.revision),version:Number(row.version),currentVersionId:String(row.current_version_id),visibility:row.visibility as SmartMaterialView["visibility"],updatedAt:asDate(row.updated_at)};}

const TAG_SELECT=`SELECT tag.*,version.name,version.aliases,version.color,version.metadata,version.path_node_ids,version.path_names,(SELECT count(*) FROM new_design.material_tag_memberships membership WHERE membership.tag_id=tag.id AND membership.status='active') member_count,(SELECT count(*) FROM new_design.material_tags child WHERE child.parent_id=tag.id AND child.status='active') child_count FROM new_design.material_tags tag JOIN new_design.material_tag_versions version ON version.id=tag.current_version_id`;
const GROUP_SELECT=`SELECT group_row.*,version.name,(SELECT count(*) FROM new_design.material_group_memberships membership WHERE membership.group_id=group_row.id AND membership.status='active') member_count FROM new_design.material_groups group_row JOIN new_design.material_group_versions version ON version.id=group_row.current_version_id`;
const VIEW_SELECT=`SELECT view_row.*,version.version,version.name,version.description,version.filter_ast,version.sort_config,version.grouping,version.display_columns,version.layout FROM new_design.smart_views view_row JOIN new_design.smart_view_versions version ON version.id=view_row.current_version_id`;

export async function getMaterialManagementWorkspace(input:ScopeInput):Promise<MaterialManagementWorkspace>{const pool=await getNewDesignPool(),client=await pool.connect();try{const scope=await resolveScope(client,input);const [tags,groups,views,memberships]=await Promise.all([
  client.query(`${TAG_SELECT} WHERE tag.space_id=$1 ORDER BY tag.status,version.name`,[scope.spaceId]),
  client.query(`${GROUP_SELECT} WHERE group_row.space_id=$1 ORDER BY group_row.status,group_row.parent_id NULLS FIRST,group_row.sort_order,version.name`,[scope.spaceId]),
  client.query(`${VIEW_SELECT} WHERE view_row.space_id=$1 ORDER BY view_row.status,version.name`,[scope.spaceId]),
  client.query(`SELECT card.id card_id,COALESCE(array_agg(DISTINCT tag_member.tag_id) FILTER(WHERE tag_member.status='active'),'{}') tag_ids,COALESCE(array_agg(DISTINCT group_member.group_id) FILTER(WHERE group_member.status='active'),'{}') group_ids FROM new_design.cards card LEFT JOIN new_design.material_tag_memberships tag_member ON tag_member.card_id=card.id LEFT JOIN new_design.material_group_memberships group_member ON group_member.card_id=card.id WHERE card.space_id=$1 GROUP BY card.id`,[scope.spaceId]),
]);return{spaceId:scope.spaceId,bookId:scope.bookId,tags:tags.rows.map(mapTag),groups:groups.rows.map(mapGroup),views:views.rows.map(mapView),memberships:memberships.rows.map(row=>({cardId:String(row.card_id),tagIds:asArray<unknown>(row.tag_ids).map(String),groupIds:asArray<unknown>(row.group_ids).map(String)}))};}finally{client.release();}}

async function existingEvent(client:PoolClient,spaceId:string,idempotencyKey:string){return (await client.query("SELECT * FROM new_design.material_management_events WHERE space_id=$1 AND idempotency_key=$2",[spaceId,idempotencyKey])).rows[0];}
async function addEvent(client:PoolClient,scope:Scope,input:{kind:string;subjectId:string;action:string;expectedRevision?:number;versionId?:string|null;detail?:Record<string,unknown>;idempotencyKey:string;actor?:string}){await client.query(`INSERT INTO new_design.material_management_events(id,space_id,book_id,subject_kind,subject_id,action,expected_revision,result_version_id,detail,idempotency_key,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10,$11)`,[randomUUID(),scope.spaceId,scope.bookId,input.kind,input.subjectId,input.action,input.expectedRevision??null,input.versionId??null,JSON.stringify(input.detail??{}),input.idempotencyKey,input.actor??ACTOR]);}

async function ensureDefaultTagDimension(client:PoolClient,spaceId:string):Promise<string>{
  const existing=(await client.query("SELECT id FROM new_design.material_tag_dimensions WHERE owner_space_id=$1 AND dimension_key='default_tags'",[spaceId])).rows[0];
  if(existing)return String(existing.id);
  const id=randomUUID(),versionId=randomUUID();
  await client.query("INSERT INTO new_design.material_tag_dimensions(id,dimension_key,name,description,scope,owner_space_id,current_version_id,created_by,updated_by) VALUES($1,'default_tags','通用标签','兼容常用标签的默认维度。','book',$2,NULL,$3,$3)",[id,spaceId,ACTOR]);
  await client.query("INSERT INTO new_design.material_tag_dimension_versions(id,dimension_id,version,name,description,status,created_by) VALUES($1,$2,1,'通用标签','兼容常用标签的默认维度。','active',$3)",[versionId,id,ACTOR]);
  await client.query("UPDATE new_design.material_tag_dimensions SET current_version_id=$2 WHERE id=$1",[id,versionId]);
  return id;
}

async function tagPath(client:PoolClient,id:string):Promise<{ids:string[];names:string[]}>{
  const row=(await client.query(`WITH RECURSIVE parents AS (
    SELECT tag.id,tag.parent_id,version.name,ARRAY[tag.id]::uuid[] ids,ARRAY[version.name]::text[] names FROM new_design.material_tags tag JOIN new_design.material_tag_versions version ON version.id=tag.current_version_id WHERE tag.id=$1
    UNION ALL SELECT parent.id,parent.parent_id,version.name,ARRAY[parent.id]::uuid[]||child.ids,ARRAY[version.name]::text[]||child.names
    FROM new_design.material_tags parent JOIN new_design.material_tag_versions version ON version.id=parent.current_version_id JOIN parents child ON child.parent_id=parent.id
  ) SELECT ids,names FROM parents WHERE parent_id IS NULL`,[id])).rows[0];
  return{ids:asArray<unknown>(row?.ids).map(String),names:asArray<unknown>(row?.names).map(String)};
}

async function refreshTagDescendantPaths(client:PoolClient,ancestorId:string,actor:string):Promise<void>{
  const descendants=(await client.query(`WITH RECURSIVE tree AS (
    SELECT tag.id,tag.parent_id,1 depth FROM new_design.material_tags tag WHERE tag.parent_id=$1
    UNION ALL SELECT child.id,child.parent_id,parent.depth+1 FROM new_design.material_tags child JOIN tree parent ON child.parent_id=parent.id
  ) SELECT tag.*,version.name,version.aliases,version.color,version.metadata FROM tree JOIN new_design.material_tags tag ON tag.id=tree.id JOIN new_design.material_tag_versions version ON version.id=tag.current_version_id ORDER BY tree.depth,tag.sort_order`,[ancestorId])).rows;
  for(const row of descendants){
    const parentPath=await tagPath(client,String(row.parent_id)),version=Number(row.revision)+1,versionId=randomUUID();
    await client.query("INSERT INTO new_design.material_tag_versions(id,tag_id,version,name,aliases,color,metadata,status,parent_id,sort_order,path_node_ids,path_names,created_by) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9,$10,$11,$12,$13)",[versionId,row.id,version,row.name,row.aliases,row.color,JSON.stringify(row.metadata??{}),row.status,row.parent_id,row.sort_order,[...parentPath.ids,row.id],[...parentPath.names,row.name],actor]);
    await client.query("UPDATE new_design.material_tags SET revision=$2,current_version_id=$3,updated_by=$4,updated_at=now() WHERE id=$1",[row.id,version,versionId,actor]);
    await client.query("SELECT new_design.register_dependency_resource('tag_version',$1,$2)",[row.id,versionId]);
  }
}

export async function createMaterialTag(scopeInput:ScopeInput,input:TagInput):Promise<MaterialTag>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput),duplicate=await existingEvent(client,scope.spaceId,input.idempotencyKey);if(duplicate){await client.query("ROLLBACK");return mapTag(assertFound((await pool.query(`${TAG_SELECT} WHERE tag.id=$1`,[duplicate.subject_id])).rows[0],"标签操作记录已存在，但标签不可读取。"));}const id=randomUUID(),versionId=randomUUID(),dimensionId=input.dimensionId??await ensureDefaultTagDimension(client,scope.spaceId);await client.query(`INSERT INTO new_design.material_tags(id,space_id,tag_key,dimension_id,parent_id,sort_order,visibility,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$8)`,[id,scope.spaceId,input.key,dimensionId,input.parentId??null,input.sortOrder??1000,input.visibility??"space",input.actor??ACTOR]);const parentPath=input.parentId?await tagPath(client,input.parentId):{ids:[],names:[]};await client.query(`INSERT INTO new_design.material_tag_versions(id,tag_id,version,name,aliases,color,metadata,status,parent_id,sort_order,path_node_ids,path_names,created_by) VALUES($1,$2,1,$3,$4,$5,$6::jsonb,'active',$7,$8,$9,$10,$11)`,[versionId,id,input.name,input.aliases,input.color??null,JSON.stringify(input.metadata),input.parentId??null,input.sortOrder??1000,[...parentPath.ids,id],[...parentPath.names,input.name],input.actor??ACTOR]);await client.query("UPDATE new_design.material_tags SET current_version_id=$2 WHERE id=$1",[id,versionId]);await client.query("SELECT new_design.register_dependency_resource('tag_version',$1,$2)",[id,versionId]);await addEvent(client,scope,{kind:"tag",subjectId:id,action:"create",versionId,idempotencyKey:input.idempotencyKey,actor:input.actor});await client.query("COMMIT");return mapTag(assertFound((await pool.query(`${TAG_SELECT} WHERE tag.id=$1`,[id])).rows[0],"标签创建后读取失败。"));}catch(error){await client.query("ROLLBACK");if((error as {code?:string}).code==="23505")throw new NewDesignError("标签标识已存在。",409);throw error;}finally{client.release();}}

export async function reviseMaterialTag(scopeInput:ScopeInput,id:string,input:TagRevisionInput,status?:"active"|"archived"):Promise<MaterialTag>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput),duplicate=await existingEvent(client,scope.spaceId,input.idempotencyKey);if(duplicate){await client.query("ROLLBACK");return mapTag(assertFound((await pool.query(`${TAG_SELECT} WHERE tag.id=$1`,[id])).rows[0],"标签不存在。"));}const row=assertFound((await client.query("SELECT * FROM new_design.material_tags WHERE id=$1 AND space_id=$2 FOR UPDATE",[id,scope.spaceId])).rows[0],"标签不存在。");if(Number(row.revision)!==input.expectedRevision)throw new NewDesignError("标签已被其他页面修改，请刷新后重试。",409);const nextStatus=status??String(row.status) as "active"|"archived",versionId=randomUUID(),version=Number(row.revision)+1,parentId=input.parentId===undefined?row.parent_id:input.parentId,sortOrder=input.sortOrder??Number(row.sort_order),parentPath=parentId?await tagPath(client,String(parentId)):{ids:[],names:[]},actor=input.actor??ACTOR;await client.query(`INSERT INTO new_design.material_tag_versions(id,tag_id,version,name,aliases,color,metadata,status,parent_id,sort_order,path_node_ids,path_names,created_by) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9,$10,$11,$12,$13)`,[versionId,id,version,input.name,input.aliases,input.color??null,JSON.stringify(input.metadata),nextStatus,parentId,sortOrder,[...parentPath.ids,id],[...parentPath.names,input.name],actor]);await client.query("UPDATE new_design.material_tags SET status=$2,revision=$3,current_version_id=$4,visibility=$5,parent_id=$6,sort_order=$7,updated_by=$8,updated_at=now() WHERE id=$1",[id,nextStatus,version,versionId,input.visibility??row.visibility,parentId,sortOrder,actor]);await client.query("SELECT new_design.register_dependency_resource('tag_version',$1,$2)",[id,versionId]);await refreshTagDescendantPaths(client,id,actor);await addEvent(client,scope,{kind:"tag",subjectId:id,action:nextStatus!==row.status?nextStatus==="archived"?"archive":"restore":parentId!==row.parent_id?"move":"revise",expectedRevision:input.expectedRevision,versionId,idempotencyKey:input.idempotencyKey,actor:input.actor,detail:{organizationOnly:true}});await client.query("COMMIT");return mapTag(assertFound((await pool.query(`${TAG_SELECT} WHERE tag.id=$1`,[id])).rows[0],"标签保存后读取失败。"));}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

async function changeTagMemberships(client:PoolClient,scope:Scope,input:{tagId:string;cardIds:string[];action:"add"|"remove";actor?:string}){const tag=assertFound((await client.query("SELECT * FROM new_design.material_tags WHERE id=$1 AND space_id=$2 AND status='active' FOR UPDATE",[input.tagId,scope.spaceId])).rows[0],"标签不存在或已归档。");for(const cardId of [...new Set(input.cardIds)]){const card=assertFound((await client.query("SELECT id,current_version_id FROM new_design.cards WHERE id=$1 AND space_id=$2",[cardId,scope.spaceId])).rows[0],"资料不属于当前空间。");let membership=(await client.query("SELECT * FROM new_design.material_tag_memberships WHERE tag_id=$1 AND card_id=$2 ORDER BY created_at DESC LIMIT 1 FOR UPDATE",[input.tagId,cardId])).rows[0];if(input.action==="add"&&membership?.status==="active"||input.action==="remove"&&membership?.status!=="active")continue;const membershipId=membership?String(membership.id):randomUUID(),revision=membership?Number(membership.revision)+1:1,versionId=randomUUID(),status=input.action==="add"?"active":"ended";if(membership)await client.query("UPDATE new_design.material_tag_memberships SET status=$2,revision=$3,current_version_id=NULL,updated_by=$4,updated_at=now() WHERE id=$1",[membershipId,status,revision,input.actor??ACTOR]);else await client.query("INSERT INTO new_design.material_tag_memberships(id,space_id,tag_id,card_id,status,revision,created_by,updated_by) VALUES($1,$2,$3,$4,$5,1,$6,$6)",[membershipId,scope.spaceId,input.tagId,cardId,status,input.actor??ACTOR]);await client.query("INSERT INTO new_design.material_tag_membership_versions(id,membership_id,revision,tag_version_id,card_version_id,status,created_by) VALUES($1,$2,$3,$4,$5,$6,$7)",[versionId,membershipId,revision,tag.current_version_id,card.current_version_id,status,input.actor??ACTOR]);await client.query("UPDATE new_design.material_tag_memberships SET current_version_id=$2 WHERE id=$1",[membershipId,versionId]);}}

export async function bulkChangeTagMemberships(scopeInput:ScopeInput,input:{tagId:string;cardIds:string[];action:"add"|"remove";idempotencyKey:string;actor?:string}):Promise<MaterialManagementWorkspace>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput);if(!await existingEvent(client,scope.spaceId,input.idempotencyKey)){await changeTagMemberships(client,scope,input);await addEvent(client,scope,{kind:"tag_membership",subjectId:input.tagId,action:input.action==="add"?"add_member":"remove_member",idempotencyKey:input.idempotencyKey,actor:input.actor,detail:{cardIds:[...new Set(input.cardIds)]}});}await client.query("COMMIT");return getMaterialManagementWorkspace(scopeInput);}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

export async function createMaterialGroup(scopeInput:ScopeInput,input:GroupInput):Promise<MaterialGroup>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput),duplicate=await existingEvent(client,scope.spaceId,input.idempotencyKey);if(duplicate){await client.query("ROLLBACK");return mapGroup(assertFound((await pool.query(`${GROUP_SELECT} WHERE group_row.id=$1`,[duplicate.subject_id])).rows[0],"分组操作记录已存在，但分组不可读取。"));}const id=randomUUID(),versionId=randomUUID();await client.query(`INSERT INTO new_design.material_groups(id,space_id,book_id,group_key,parent_id,sort_order,visibility,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$8)`,[id,scope.spaceId,scope.bookId,input.key,input.parentId??null,input.sortOrder,input.visibility??"space",input.actor??ACTOR]);await client.query(`INSERT INTO new_design.material_group_versions(id,group_id,version,name,parent_id,sort_order,status,created_by) VALUES($1,$2,1,$3,$4,$5,'active',$6)`,[versionId,id,input.name,input.parentId??null,input.sortOrder,input.actor??ACTOR]);await client.query("UPDATE new_design.material_groups SET current_version_id=$2 WHERE id=$1",[id,versionId]);await client.query("SELECT new_design.register_dependency_resource('material_group_version',$1,$2)",[id,versionId]);await addEvent(client,scope,{kind:"group",subjectId:id,action:"create",versionId,idempotencyKey:input.idempotencyKey,actor:input.actor});await client.query("COMMIT");return mapGroup(assertFound((await pool.query(`${GROUP_SELECT} WHERE group_row.id=$1`,[id])).rows[0],"分组创建后读取失败。"));}catch(error){await client.query("ROLLBACK");if((error as {code?:string}).code==="23505")throw new NewDesignError("分组标识已存在。",409);throw error;}finally{client.release();}}

export async function reviseMaterialGroup(scopeInput:ScopeInput,id:string,input:GroupRevisionInput):Promise<MaterialGroup>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput);if(await existingEvent(client,scope.spaceId,input.idempotencyKey)){await client.query("ROLLBACK");return mapGroup(assertFound((await pool.query(`${GROUP_SELECT} WHERE group_row.id=$1`,[id])).rows[0],"分组不存在。"));}const row=assertFound((await client.query("SELECT * FROM new_design.material_groups WHERE id=$1 AND space_id=$2 FOR UPDATE",[id,scope.spaceId])).rows[0],"分组不存在。");if(Number(row.revision)!==input.expectedRevision)throw new NewDesignError("分组已被其他页面修改，请刷新后重试。",409);const version=Number(row.revision)+1,versionId=randomUUID(),action=input.parentId!==undefined&&input.parentId!==row.parent_id?"move":input.sortOrder!==Number(row.sort_order)?"reorder":"revise";await client.query("UPDATE new_design.material_groups SET parent_id=$2,sort_order=$3,revision=$4,current_version_id=NULL,visibility=$5,updated_by=$6,updated_at=now() WHERE id=$1",[id,input.parentId??null,input.sortOrder,version,input.visibility??row.visibility,input.actor??ACTOR]);await client.query("INSERT INTO new_design.material_group_versions(id,group_id,version,name,parent_id,sort_order,status,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)",[versionId,id,version,input.name,input.parentId??null,input.sortOrder,row.status,input.actor??ACTOR]);await client.query("UPDATE new_design.material_groups SET current_version_id=$2 WHERE id=$1",[id,versionId]);await client.query("SELECT new_design.register_dependency_resource('material_group_version',$1,$2)",[id,versionId]);await addEvent(client,scope,{kind:"group",subjectId:id,action,expectedRevision:input.expectedRevision,versionId,idempotencyKey:input.idempotencyKey,actor:input.actor});await client.query("COMMIT");return mapGroup(assertFound((await pool.query(`${GROUP_SELECT} WHERE group_row.id=$1`,[id])).rows[0],"分组保存后读取失败。"));}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

async function versionGroupStatus(client:PoolClient,row:Record<string,unknown>,status:"active"|"archived",actor:string){const version=Number(row.revision)+1,versionId=randomUUID(),current=assertFound((await client.query("SELECT name FROM new_design.material_group_versions WHERE id=$1",[row.current_version_id])).rows[0],"分组版本不存在。");await client.query("UPDATE new_design.material_groups SET status=$2,revision=$3,current_version_id=NULL,updated_by=$4,updated_at=now() WHERE id=$1",[row.id,status,version,actor]);await client.query("INSERT INTO new_design.material_group_versions(id,group_id,version,name,parent_id,sort_order,status,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)",[versionId,row.id,version,current.name,row.parent_id,row.sort_order,status,actor]);await client.query("UPDATE new_design.material_groups SET current_version_id=$2 WHERE id=$1",[row.id,versionId]);await client.query("SELECT new_design.register_dependency_resource('material_group_version',$1,$2)",[row.id,versionId]);return versionId;}

export async function archiveMaterialGroup(scopeInput:ScopeInput,id:string,input:{expectedRevision:number;childMode:"promote"|"archive_tree";idempotencyKey:string;actor?:string}):Promise<MaterialManagementWorkspace>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput);if(!await existingEvent(client,scope.spaceId,input.idempotencyKey)){const row=assertFound((await client.query("SELECT * FROM new_design.material_groups WHERE id=$1 AND space_id=$2 FOR UPDATE",[id,scope.spaceId])).rows[0],"分组不存在。");if(Number(row.revision)!==input.expectedRevision)throw new NewDesignError("分组已被其他页面修改，请刷新后重试。",409);const actor=input.actor??ACTOR;if(input.childMode==="promote"){const children=(await client.query("SELECT * FROM new_design.material_groups WHERE parent_id=$1 AND status='active' FOR UPDATE",[id])).rows;for(const child of children){child.parent_id=row.parent_id;child.revision=Number(child.revision)+1;const childVersion=randomUUID(),name=(await client.query("SELECT name FROM new_design.material_group_versions WHERE id=$1",[child.current_version_id])).rows[0].name;await client.query("UPDATE new_design.material_groups SET parent_id=$2,revision=$3,current_version_id=NULL,updated_by=$4,updated_at=now() WHERE id=$1",[child.id,row.parent_id,child.revision,actor]);await client.query("INSERT INTO new_design.material_group_versions(id,group_id,version,name,parent_id,sort_order,status,created_by) VALUES($1,$2,$3,$4,$5,$6,'active',$7)",[childVersion,child.id,child.revision,name,row.parent_id,child.sort_order,actor]);await client.query("UPDATE new_design.material_groups SET current_version_id=$2 WHERE id=$1",[child.id,childVersion]);await client.query("SELECT new_design.register_dependency_resource('material_group_version',$1,$2)",[child.id,childVersion]);}}else{const descendants=(await client.query(`WITH RECURSIVE tree AS (SELECT * FROM new_design.material_groups WHERE parent_id=$1 AND status='active' UNION ALL SELECT child.* FROM tree JOIN new_design.material_groups child ON child.parent_id=tree.id WHERE child.status='active') SELECT * FROM tree ORDER BY id FOR UPDATE`,[id])).rows;for(const child of descendants)await versionGroupStatus(client,child,"archived",actor);}const versionId=await versionGroupStatus(client,row,"archived",actor);await addEvent(client,scope,{kind:"group",subjectId:id,action:input.childMode==="promote"?"promote_children":"archive_tree",expectedRevision:input.expectedRevision,versionId,idempotencyKey:input.idempotencyKey,actor,detail:{organizationOnly:true}});}await client.query("COMMIT");return getMaterialManagementWorkspace(scopeInput);}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

async function changeGroupMemberships(client:PoolClient,scope:Scope,input:{groupId:string;cardIds:string[];action:"add"|"remove";actor?:string}){const group=assertFound((await client.query("SELECT * FROM new_design.material_groups WHERE id=$1 AND space_id=$2 AND status='active' FOR UPDATE",[input.groupId,scope.spaceId])).rows[0],"分组不存在或已归档。");for(const cardId of [...new Set(input.cardIds)]){const card=assertFound((await client.query("SELECT id,current_version_id FROM new_design.cards WHERE id=$1 AND space_id=$2",[cardId,scope.spaceId])).rows[0],"资料不属于当前空间。");let membership=(await client.query("SELECT * FROM new_design.material_group_memberships WHERE group_id=$1 AND card_id=$2 ORDER BY created_at DESC LIMIT 1 FOR UPDATE",[input.groupId,cardId])).rows[0];if(input.action==="add"&&membership?.status==="active"||input.action==="remove"&&membership?.status!=="active")continue;const membershipId=membership?String(membership.id):randomUUID(),revision=membership?Number(membership.revision)+1:1,versionId=randomUUID(),status=input.action==="add"?"active":"ended";if(membership)await client.query("UPDATE new_design.material_group_memberships SET status=$2,revision=$3,current_version_id=NULL,updated_by=$4,updated_at=now() WHERE id=$1",[membershipId,status,revision,input.actor??ACTOR]);else await client.query("INSERT INTO new_design.material_group_memberships(id,space_id,group_id,card_id,status,revision,created_by,updated_by) VALUES($1,$2,$3,$4,$5,1,$6,$6)",[membershipId,scope.spaceId,input.groupId,cardId,status,input.actor??ACTOR]);await client.query("INSERT INTO new_design.material_group_membership_versions(id,membership_id,revision,group_version_id,card_version_id,sort_order,status,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)",[versionId,membershipId,revision,group.current_version_id,card.current_version_id,membership?.sort_order??1000,status,input.actor??ACTOR]);await client.query("UPDATE new_design.material_group_memberships SET current_version_id=$2 WHERE id=$1",[membershipId,versionId]);}}

export async function bulkChangeGroupMemberships(scopeInput:ScopeInput,input:{groupId:string;cardIds:string[];action:"add"|"remove";idempotencyKey:string;actor?:string}):Promise<MaterialManagementWorkspace>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput);if(!await existingEvent(client,scope.spaceId,input.idempotencyKey)){await changeGroupMemberships(client,scope,input);await addEvent(client,scope,{kind:"group_membership",subjectId:input.groupId,action:input.action==="add"?"add_member":"remove_member",idempotencyKey:input.idempotencyKey,actor:input.actor,detail:{cardIds:[...new Set(input.cardIds)]}});}await client.query("COMMIT");return getMaterialManagementWorkspace(scopeInput);}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

export async function createSmartMaterialView(scopeInput:ScopeInput,input:SmartViewInput):Promise<SmartMaterialView>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput),duplicate=await existingEvent(client,scope.spaceId,input.idempotencyKey);if(duplicate){await client.query("ROLLBACK");return mapView(assertFound((await pool.query(`${VIEW_SELECT} WHERE view_row.id=$1`,[duplicate.subject_id])).rows[0],"智能视图操作记录已存在，但视图不可读取。"));}const id=randomUUID(),versionId=randomUUID();await client.query("INSERT INTO new_design.smart_views(id,space_id,book_id,view_key,base_view_key,visibility,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$7)",[id,scope.spaceId,scope.bookId,input.key,input.baseViewKey??null,input.visibility??"space",input.actor??ACTOR]);await client.query(`INSERT INTO new_design.smart_view_versions(id,smart_view_id,version,name,description,filter_ast,sort_config,grouping,display_columns,layout,created_by) VALUES($1,$2,1,$3,$4,$5::jsonb,$6::jsonb,$7::jsonb,$8,$9::jsonb,$10)`,[versionId,id,input.name,input.description,JSON.stringify(input.filter),JSON.stringify(input.sort),JSON.stringify(input.grouping),input.displayColumns,JSON.stringify(input.layout),input.actor??ACTOR]);await client.query("UPDATE new_design.smart_views SET current_version_id=$2 WHERE id=$1",[id,versionId]);await client.query("SELECT new_design.register_dependency_resource('smart_view_version',$1,$2)",[id,versionId]);await addEvent(client,scope,{kind:"smart_view",subjectId:id,action:"create",versionId,idempotencyKey:input.idempotencyKey,actor:input.actor});await client.query("COMMIT");return mapView(assertFound((await pool.query(`${VIEW_SELECT} WHERE view_row.id=$1`,[id])).rows[0],"智能视图创建后读取失败。"));}catch(error){await client.query("ROLLBACK");if((error as {code?:string}).code==="23505")throw new NewDesignError("视图标识已存在。",409);throw error;}finally{client.release();}}

export async function reviseSmartMaterialView(scopeInput:ScopeInput,id:string,input:SmartViewRevisionInput,status?:"active"|"archived",copiedFromVersionId?:string|null):Promise<SmartMaterialView>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput);if(await existingEvent(client,scope.spaceId,input.idempotencyKey)){await client.query("ROLLBACK");return mapView(assertFound((await pool.query(`${VIEW_SELECT} WHERE view_row.id=$1`,[id])).rows[0],"智能视图不存在。"));}const row=assertFound((await client.query("SELECT * FROM new_design.smart_views WHERE id=$1 AND space_id=$2 FOR UPDATE",[id,scope.spaceId])).rows[0],"智能视图不存在。");if(Number(row.revision)!==input.expectedRevision)throw new NewDesignError("智能视图已被其他页面修改，请刷新后重试。",409);const version=Number(row.revision)+1,versionId=randomUUID(),nextStatus=status??row.status;await client.query(`INSERT INTO new_design.smart_view_versions(id,smart_view_id,version,name,description,filter_ast,sort_config,grouping,display_columns,layout,copied_from_version_id,created_by) VALUES($1,$2,$3,$4,$5,$6::jsonb,$7::jsonb,$8::jsonb,$9,$10::jsonb,$11,$12)`,[versionId,id,version,input.name,input.description,JSON.stringify(input.filter),JSON.stringify(input.sort),JSON.stringify(input.grouping),input.displayColumns,JSON.stringify(input.layout),copiedFromVersionId??null,input.actor??ACTOR]);await client.query("UPDATE new_design.smart_views SET status=$2,revision=$3,current_version_id=$4,visibility=$5,updated_by=$6,updated_at=now() WHERE id=$1",[id,nextStatus,version,versionId,input.visibility??row.visibility,input.actor??ACTOR]);await client.query("SELECT new_design.register_dependency_resource('smart_view_version',$1,$2)",[id,versionId]);await addEvent(client,scope,{kind:"smart_view",subjectId:id,action:nextStatus!==row.status?nextStatus==="archived"?"archive":"restore":"revise",expectedRevision:input.expectedRevision,versionId,idempotencyKey:input.idempotencyKey,actor:input.actor,detail:{queryDefinitionOnly:true}});await client.query("COMMIT");return mapView(assertFound((await pool.query(`${VIEW_SELECT} WHERE view_row.id=$1`,[id])).rows[0],"智能视图保存后读取失败。"));}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

export async function copySmartMaterialView(scopeInput:ScopeInput,id:string,input:{key:string;name:string;idempotencyKey:string;actor?:string}):Promise<SmartMaterialView>{const workspace=await getMaterialManagementWorkspace(scopeInput),source=assertFound(workspace.views.find(view=>view.id===id),"智能视图不存在或不属于当前空间。");return createSmartMaterialView(scopeInput,{key:input.key,name:input.name,description:source.description,baseViewKey:null,filter:source.filter,sort:source.sort,grouping:source.grouping,displayColumns:source.displayColumns,layout:source.layout,idempotencyKey:input.idempotencyKey,actor:input.actor});}

const CONDITION_SQL:Record<MaterialFilterCondition["field"],Partial<Record<MaterialFilterCondition["operator"],(index:number)=>string>>>={
  content_type:{equals:i=>`type.type_key=$${i}`,not_equals:i=>`type.type_key<>$${i}`,in:i=>`type.type_key=ANY($${i}::text[])`,not_in:i=>`NOT(type.type_key=ANY($${i}::text[]))`},
  tag:{equals:i=>`EXISTS(SELECT 1 FROM new_design.material_tag_memberships tm JOIN new_design.material_tags tag ON tag.id=tm.tag_id JOIN new_design.material_tag_versions version ON version.id=tag.current_version_id WHERE tm.card_id=card.id AND tm.status='active' AND tag.status='active' AND EXISTS(SELECT 1 FROM unnest(version.path_node_ids) path_id JOIN new_design.material_tags ancestor ON ancestor.id=path_id WHERE ancestor.id=path_id AND (ancestor.id::text=$${i} OR ancestor.tag_key=$${i})))`,in:i=>`EXISTS(SELECT 1 FROM new_design.material_tag_memberships tm JOIN new_design.material_tags tag ON tag.id=tm.tag_id JOIN new_design.material_tag_versions version ON version.id=tag.current_version_id WHERE tm.card_id=card.id AND tm.status='active' AND tag.status='active' AND EXISTS(SELECT 1 FROM unnest(version.path_node_ids) path_id JOIN new_design.material_tags ancestor ON ancestor.id=path_id WHERE ancestor.id=path_id AND (ancestor.id::text=ANY($${i}::text[]) OR ancestor.tag_key=ANY($${i}::text[]))))`,exists:()=>`EXISTS(SELECT 1 FROM new_design.material_tag_memberships tm WHERE tm.card_id=card.id AND tm.status='active')`,not_exists:()=>`NOT EXISTS(SELECT 1 FROM new_design.material_tag_memberships tm WHERE tm.card_id=card.id AND tm.status='active')`},
  card_status:{equals:i=>`card.status=$${i}`,in:i=>`card.status=ANY($${i}::text[])`},
  canonical_status:{equals:i=>`EXISTS(SELECT 1 FROM new_design.canonical_facts fact WHERE (fact.subject_card_id=card.id OR fact.object_card_id=card.id) AND fact.status=$${i})`,in:i=>`EXISTS(SELECT 1 FROM new_design.canonical_facts fact WHERE (fact.subject_card_id=card.id OR fact.object_card_id=card.id) AND fact.status=ANY($${i}::text[]))`},
  candidate_status:{equals:i=>`EXISTS(SELECT 1 FROM new_design.research_candidate_adoptions adoption JOIN new_design.research_candidates candidate ON candidate.id=adoption.candidate_id WHERE adoption.target_card_id=card.id AND candidate.status=$${i})`,in:i=>`EXISTS(SELECT 1 FROM new_design.research_candidate_adoptions adoption JOIN new_design.research_candidates candidate ON candidate.id=adoption.candidate_id WHERE adoption.target_card_id=card.id AND candidate.status=ANY($${i}::text[]))`},
  chapter:{equals:i=>`(card.id::text=$${i} OR EXISTS(SELECT 1 FROM new_design.narrative_placements placement WHERE placement.subject_card_id=card.id AND placement.chapter_card_id::text=$${i} AND placement.status='active'))`,in:i=>`(card.id::text=ANY($${i}::text[]) OR EXISTS(SELECT 1 FROM new_design.narrative_placements placement WHERE placement.subject_card_id=card.id AND placement.chapter_card_id::text=ANY($${i}::text[]) AND placement.status='active'))`},
  volume:{equals:i=>`(card.id::text=$${i} OR EXISTS(SELECT 1 FROM new_design.planning_objects object WHERE object.card_id=card.id AND (object.id::text=$${i} OR object.parent_object_id::text=$${i}) AND object.status='active'))`,in:i=>`(card.id::text=ANY($${i}::text[]) OR EXISTS(SELECT 1 FROM new_design.planning_objects object WHERE object.card_id=card.id AND (object.id::text=ANY($${i}::text[]) OR object.parent_object_id::text=ANY($${i}::text[])) AND object.status='active'))`},
  story_time:{gte:i=>`time.start_order>=$${i}::numeric`,lte:i=>`time.start_order<=$${i}::numeric`,between:i=>`time.start_order BETWEEN ($${i}::jsonb->>0)::numeric AND ($${i}::jsonb->>1)::numeric`,exists:()=>`time.card_id IS NOT NULL`,not_exists:()=>`time.card_id IS NULL`},
  relation_exists:{exists:()=>`EXISTS(SELECT 1 FROM new_design.card_relations relation WHERE relation.status='active' AND (relation.source_card_id=card.id OR relation.target_card_id=card.id))`,not_exists:()=>`NOT EXISTS(SELECT 1 FROM new_design.card_relations relation WHERE relation.status='active' AND (relation.source_card_id=card.id OR relation.target_card_id=card.id))`},
  association_exists:{exists:()=>`EXISTS(SELECT 1 FROM new_design.card_mounts mount WHERE mount.card_id=card.id AND mount.status='active')`,not_exists:()=>`NOT EXISTS(SELECT 1 FROM new_design.card_mounts mount WHERE mount.card_id=card.id AND mount.status='active')`},
  source:{equals:i=>`current_version.source=$${i}`,in:i=>`current_version.source=ANY($${i}::text[])`},
  updated_at:{gte:i=>`card.updated_at>=$${i}::timestamptz`,lte:i=>`card.updated_at<=$${i}::timestamptz`,between:i=>`card.updated_at BETWEEN ($${i}::jsonb->>0)::timestamptz AND ($${i}::jsonb->>1)::timestamptz`},
};
function hasField(node:MaterialFilterNode,field:MaterialFilterCondition["field"]):boolean{return node.kind==="condition"?node.field===field:node.items.some(item=>hasField(item,field));}
function compileFilter(node:MaterialFilterNode,params:unknown[]):string{if(node.kind==="group"){if(!node.items.length)return"TRUE";return`(${node.items.map(item=>compileFilter(item,params)).join(node.operator==="and"?" AND ":" OR ")})`;}const factory=CONDITION_SQL[node.field]?.[node.operator];if(!factory)throw new NewDesignError(`筛选字段 ${node.field} 不支持 ${node.operator}。`,422);const needsValue=!['exists','not_exists'].includes(node.operator);if(needsValue){const value=node.operator==="between"?JSON.stringify(node.value):node.value;params.push(value);}return factory(params.length);}
const SORT_SQL:Record<MaterialSortRule["field"],string>={title:"card.title",content_type:"type.name",updated_at:"card.updated_at",created_at:"card.created_at",story_time:"time.start_order"};

export async function queryMaterials(scopeInput:ScopeInput,input:{viewId?:string;filter?:MaterialFilterNode;sort?:MaterialSortRule[];cursor?:string;limit?:number}):Promise<MaterialQueryPage>{const pool=await getNewDesignPool(),client=await pool.connect();try{const scope=await resolveScope(client,scopeInput);let filter=input.filter??({kind:"group",operator:"and",items:[]} as MaterialFilterNode),sort=input.sort??[{field:"updated_at",direction:"desc"} as MaterialSortRule];if(input.viewId){const view=assertFound((await client.query(`${VIEW_SELECT} WHERE view_row.id=$1 AND view_row.space_id=$2 AND view_row.status='active'`,[input.viewId,scope.spaceId])).rows[0],"智能视图不存在或已归档。");filter=view.filter_ast as MaterialFilterNode;sort=asArray<MaterialSortRule>(view.sort_config);}const params:unknown[]=[scope.spaceId],parts=[compileFilter(filter,params)];if(!hasField(filter,"card_status"))parts.unshift("card.status='active'");if(input.cursor){params.push(input.cursor);parts.push(`card.id>$${params.length}::uuid`);}const where=parts.join(" AND "),limit=Math.min(100,Math.max(1,input.limit??40)),order=sort.slice(0,3).map(rule=>`${SORT_SQL[rule.field]} ${rule.direction.toUpperCase()} NULLS LAST`).concat("card.id ASC").join(",");params.push(limit+1);const rows=(await client.query(`SELECT card.*,type.type_key,type.name card_type_name,version.version type_version,time.start_order story_time_start,organization.tags,organization.groups FROM new_design.cards card JOIN new_design.card_types type ON type.id=card.card_type_id JOIN new_design.card_type_versions version ON version.id=card.type_version_id JOIN new_design.card_versions current_version ON current_version.id=card.current_version_id LEFT JOIN new_design.story_time_positions time ON time.card_id=card.id LEFT JOIN new_design.material_card_organization organization ON organization.card_id=card.id WHERE card.space_id=$1 AND ${where} ORDER BY ${order} LIMIT $${params.length}`,params)).rows;const countParams=params.slice(0,-1),count=await client.query(`SELECT LEAST(count(*),10001) total FROM new_design.cards card JOIN new_design.card_types type ON type.id=card.card_type_id JOIN new_design.card_versions current_version ON current_version.id=card.current_version_id LEFT JOIN new_design.story_time_positions time ON time.card_id=card.id WHERE card.space_id=$1 AND ${where}`,countParams);const items=rows.slice(0,limit).map(row=>({id:String(row.id),cardTypeId:String(row.card_type_id),cardTypeName:String(row.card_type_name),title:String(row.title),status:row.status,revision:Number(row.revision),typeVersionId:String(row.type_version_id),typeVersion:Number(row.type_version),values:row.values,createdAt:asDate(row.created_at),updatedAt:asDate(row.updated_at),archivedAt:row.archived_at?asDate(row.archived_at):null,typeKey:String(row.type_key),tagIds:asArray<{id:string}>(row.tags).map(item=>String(item.id)),groupIds:asArray<{id:string}>(row.groups).map(item=>String(item.id)),storyTimeStart:row.story_time_start===null?null:Number(row.story_time_start)}));return{items,nextCursor:rows.length>limit?items.at(-1)?.id??null:null,totalCapped:Number(count.rows[0]?.total??0)};}finally{client.release();}}

async function buildArchiveImpacts(client:PoolClient,scope:Scope,cardId:string):Promise<CardArchiveImpactItem[]>{const definitions:Array<{key:string;label:string;level:CardArchiveImpactItem["level"];sql:string}>=[
  {key:"primary_forms",label:"以此资料为主项的创作表单",level:"blocking",sql:"SELECT id,title label FROM new_design.card_group_form_instances WHERE primary_card_id=$1 LIMIT 6"},
  {key:"mounts",label:"创作表单中的关联引用",level:"risk",sql:"SELECT id,slot_key label FROM new_design.card_mounts WHERE card_id=$1 AND status='active' LIMIT 6"},
  {key:"relations",label:"资料关系",level:"risk",sql:"SELECT id,relation_type_id::text label FROM new_design.card_relations WHERE (source_card_id=$1 OR target_card_id=$1) AND status='active' LIMIT 6"},
  {key:"canonical_facts",label:"正式事实",level:"recompute",sql:"SELECT id,predicate label FROM new_design.canonical_facts WHERE (subject_card_id=$1 OR object_card_id=$1) AND status IN ('proposed','confirmed','stale') LIMIT 6"},
  {key:"story_timings",label:"故事时间",level:"recompute",sql:"SELECT id,COALESCE(start_label,time_mode) label FROM new_design.story_event_timings WHERE (event_card_id=$1 OR relative_to_event_card_id=$1) AND status='active' LIMIT 6"},
  {key:"narrative",label:"章节与正文位置",level:"risk",sql:"SELECT id,role label FROM new_design.narrative_placements WHERE (subject_card_id=$1 OR chapter_card_id=$1 OR scene_card_id=$1) AND status='active' LIMIT 6"},
  {key:"text_anchors",label:"正文锚点",level:"risk",sql:"SELECT id,role label FROM new_design.text_anchors WHERE subject_card_id=$1 OR chapter_card_id=$1 OR scene_card_id=$1 LIMIT 6"},
  {key:"state_changes",label:"状态变化记录",level:"recompute",sql:"SELECT id,state_key label FROM new_design.state_changes WHERE (subject_kind='card' AND subject_id=$1) OR cause_event_card_id=$1 LIMIT 6"},
  {key:"knowledge",label:"角色与读者认知记录",level:"recompute",sql:"SELECT id,holder_key label FROM new_design.knowledge_state_changes WHERE holder_card_id=$1 UNION ALL SELECT id,predicate label FROM new_design.epistemic_claims WHERE subject_card_id=$1 OR object_card_id=$1 LIMIT 6"},
  {key:"planning",label:"卷章场景规划",level:"blocking",sql:"SELECT id,title label FROM new_design.planning_objects WHERE card_id=$1 AND status='active' LIMIT 6"},
  {key:"research_adoptions",label:"研究提案采用记录",level:"information",sql:"SELECT id,action label FROM new_design.research_candidate_adoptions WHERE target_card_id=$1 LIMIT 6"},
  {key:"assets",label:"附加素材",level:"risk",sql:"SELECT id,label FROM new_design.asset_mounts WHERE owner_kind='card_version' AND owner_stable_id=$1 AND status='active' LIMIT 6"},
  {key:"dependencies",label:"待重新计算的下游资料",level:"recompute",sql:"SELECT edge.id,resource.resource_kind label FROM new_design.dependency_resources source JOIN new_design.dependency_edges edge ON edge.source_resource_id=source.id AND edge.status='active' JOIN new_design.dependency_resources resource ON resource.id=edge.derived_resource_id WHERE source.resource_kind='card_version' AND source.stable_object_id=$1 LIMIT 6"},
  {key:"tags_groups",label:"标签与分组引用",level:"information",sql:"SELECT id,'组织引用' label FROM new_design.material_tag_memberships WHERE card_id=$1 AND status='active' UNION ALL SELECT id,'组织引用' label FROM new_design.material_group_memberships WHERE card_id=$1 AND status='active' LIMIT 6"},
];const impacts:CardArchiveImpactItem[]=[];for(const definition of definitions){const samples=(await client.query(definition.sql,[cardId])).rows.map(row=>({id:String(row.id),label:String(row.label??"")}));const countSql=`SELECT count(*) value FROM (${definition.sql.replace(/ LIMIT 6$/,'')}) impact_rows`,count=Number((await client.query(countSql,[cardId])).rows[0]?.value??0);if(count)impacts.push({key:definition.key,label:definition.label,count,level:definition.level,samples});}return impacts;}

export async function previewCardArchive(scopeInput:ScopeInput,cardId:string,input:{expectedRevision:number;actor?:string}):Promise<CardArchivePreview>{const pool=await getNewDesignPool(),client=await pool.connect();try{const scope=await resolveScope(client,scopeInput),card=assertFound((await client.query("SELECT id,revision,status FROM new_design.cards WHERE id=$1 AND space_id=$2",[cardId,scope.spaceId])).rows[0],"资料不存在。");if(card.status!=="active")throw new NewDesignError("资料处于归档状态。",409);if(Number(card.revision)!==input.expectedRevision)throw new NewDesignError("资料已更新，请重新生成归档影响预览。",409);const impacts=await buildArchiveImpacts(client,scope,cardId),snapshot={spaceId:scope.spaceId,bookId:scope.bookId,cardId,expectedRevision:input.expectedRevision,impacts},snapshotHash=stableHash(snapshot),confirmationToken=randomUUID(),tokenHash=createHash("sha256").update(confirmationToken).digest("hex"),blockingCount=impacts.filter(item=>item.level==="blocking").reduce((sum,item)=>sum+item.count,0),riskCount=impacts.filter(item=>item.level==="risk").reduce((sum,item)=>sum+item.count,0),recomputeCount=impacts.filter(item=>item.level==="recompute").reduce((sum,item)=>sum+item.count,0),decision=blockingCount?"blocked":riskCount||recomputeCount?"risk_confirmation":"ready",id=randomUUID(),expiresAt=new Date(Date.now()+15*60*1000).toISOString();await client.query(`INSERT INTO new_design.card_archive_previews(id,space_id,book_id,card_id,expected_revision,dependency_snapshot,snapshot_hash,confirmation_token_hash,decision,expires_at,created_by) VALUES($1,$2,$3,$4,$5,$6::jsonb,$7,$8,$9,$10,$11)`,[id,scope.spaceId,scope.bookId,cardId,input.expectedRevision,JSON.stringify(snapshot),snapshotHash,tokenHash,decision,expiresAt,input.actor??ACTOR]);return{id,spaceId:scope.spaceId,bookId:scope.bookId,cardId,expectedRevision:input.expectedRevision,snapshotHash,confirmationToken,decision,expiresAt,impacts,blockingCount,riskCount,recomputeCount};}finally{client.release();}}

function mapCard(row:Record<string,unknown>):CardSummary{return{id:String(row.id),cardTypeId:String(row.card_type_id),cardTypeName:String(row.card_type_name),title:String(row.title),status:row.status as CardSummary["status"],revision:Number(row.revision),typeVersionId:String(row.type_version_id),typeVersion:Number(row.type_version),values:row.values as Record<string,unknown>,createdAt:asDate(row.created_at),updatedAt:asDate(row.updated_at),archivedAt:row.archived_at?asDate(row.archived_at):null};}
async function writeCardStatusVersion(client:PoolClient,card:Record<string,unknown>,status:"active"|"archived",actor:string){const versionId=randomUUID(),nextRevision=Number(card.revision)+1,source=status==="archived"?"archive":"restore";await client.query(`INSERT INTO new_design.card_versions(id,card_id,revision,type_version_id,title,values,source,form_version_id,form_resolution_kind) SELECT $1,card.id,$2,card.type_version_id,card.title,card.values,$3,previous.form_version_id,previous.form_resolution_kind FROM new_design.cards card JOIN new_design.card_versions previous ON previous.id=card.current_version_id WHERE card.id=$4`,[versionId,nextRevision,source,card.id]);await client.query(`INSERT INTO new_design.card_version_local_values(card_version_id,field_definition_id,field_definition_version_id,value) SELECT $1,field_definition_id,field_definition_version_id,value FROM new_design.card_version_local_values WHERE card_version_id=$2`,[versionId,card.current_version_id]);await client.query("UPDATE new_design.cards SET status=$2,revision=$3,current_version_id=$4,updated_at=now(),archived_at=CASE WHEN $2='archived' THEN now() ELSE NULL END WHERE id=$1",[card.id,status,nextRevision,versionId]);const oldResource=String((await client.query("SELECT new_design.register_dependency_resource('card_version',$1,$2) id",[card.id,card.current_version_id])).rows[0].id),newResource=String((await client.query("SELECT new_design.register_dependency_resource('card_version',$1,$2) id",[card.id,versionId])).rows[0].id),changeId=randomUUID();await client.query("SELECT new_design.invalidate_registered_resource($1,$2,$3,'manual',$4,$5,$6)",[oldResource,newResource,status==="archived"?"资料归档，依赖此资料的结果需要复核。":"资料恢复使用，依赖结果需要复核。",changeId,`card-${source}:${changeId}`,status==="archived"?"invalid":"stale"]);return{versionId,nextRevision,actor};}

export async function confirmCardArchive(scopeInput:ScopeInput,cardId:string,input:{previewId:string;confirmationToken:string;snapshotHash:string;expectedRevision:number;acceptRisk:boolean;idempotencyKey:string;actor?:string}):Promise<CardArchiveReceipt>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput),prior=(await client.query("SELECT event.*,card.*,type.name card_type_name,version.version type_version FROM new_design.card_archive_events event JOIN new_design.cards card ON card.id=event.card_id JOIN new_design.card_types type ON type.id=card.card_type_id JOIN new_design.card_type_versions version ON version.id=card.type_version_id WHERE event.space_id=$1 AND event.idempotency_key=$2",[scope.spaceId,input.idempotencyKey])).rows[0];if(prior){await client.query("ROLLBACK");return{id:String(prior.id),card:mapCard(prior),riskAccepted:Boolean(prior.risk_accepted),createdAt:asDate(prior.created_at)};}const preview=assertFound((await client.query("SELECT * FROM new_design.card_archive_previews WHERE id=$1 AND card_id=$2 AND space_id=$3 FOR UPDATE",[input.previewId,cardId,scope.spaceId])).rows[0],"归档影响预览不存在。");if(preview.consumed_at||new Date(String(preview.expires_at)).getTime()<=Date.now())throw new NewDesignError("归档影响预览已过期，请重新检查。",409);if(String(preview.snapshot_hash)!==input.snapshotHash||String(preview.confirmation_token_hash)!==createHash("sha256").update(input.confirmationToken).digest("hex"))throw new NewDesignError("归档确认凭据不匹配，请重新检查。",409);const card=assertFound((await client.query("SELECT * FROM new_design.cards WHERE id=$1 AND space_id=$2 FOR UPDATE",[cardId,scope.spaceId])).rows[0],"资料不存在。");if(Number(card.revision)!==input.expectedRevision||Number(preview.expected_revision)!==input.expectedRevision)throw new NewDesignError("资料已更新，请重新生成归档影响预览。",409);const impacts=await buildArchiveImpacts(client,scope,cardId),snapshot={spaceId:scope.spaceId,bookId:scope.bookId,cardId,expectedRevision:input.expectedRevision,impacts};if(stableHash(snapshot)!==input.snapshotHash)throw new NewDesignError("引用关系已经变化，请重新生成归档影响预览。",409);if(preview.decision==="blocked")throw new NewDesignError("此资料仍是创作表单主项，需先调整表单后再归档。",409);if(preview.decision==="risk_confirmation"&&!input.acceptRisk)throw new NewDesignError("此资料仍有引用或待重算影响，请确认风险后再归档。",422);const result=await writeCardStatusVersion(client,card,"archived",input.actor??ACTOR),eventId=randomUUID();await client.query("UPDATE new_design.card_archive_previews SET consumed_at=now() WHERE id=$1",[preview.id]);await client.query(`INSERT INTO new_design.card_archive_events(id,preview_id,space_id,book_id,card_id,from_status,to_status,from_revision,to_revision,snapshot_hash,risk_accepted,idempotency_key,created_by) VALUES($1,$2,$3,$4,$5,'active','archived',$6,$7,$8,$9,$10,$11)`,[eventId,preview.id,scope.spaceId,scope.bookId,cardId,input.expectedRevision,result.nextRevision,input.snapshotHash,input.acceptRisk,input.idempotencyKey,input.actor??ACTOR]);await client.query("COMMIT");const saved=assertFound((await pool.query(`SELECT card.*,type.name card_type_name,version.version type_version FROM new_design.cards card JOIN new_design.card_types type ON type.id=card.card_type_id JOIN new_design.card_type_versions version ON version.id=card.type_version_id WHERE card.id=$1`,[cardId])).rows[0],"归档后资料不可读取。");return{id:eventId,card:mapCard(saved),riskAccepted:input.acceptRisk,createdAt:new Date().toISOString()};}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

export async function restoreArchivedCard(scopeInput:ScopeInput,cardId:string,input:{expectedRevision:number;idempotencyKey:string;actor?:string}):Promise<CardArchiveReceipt>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const scope=await resolveScope(client,scopeInput),prior=(await client.query("SELECT id,risk_accepted,created_at FROM new_design.card_archive_events WHERE space_id=$1 AND idempotency_key=$2",[scope.spaceId,input.idempotencyKey])).rows[0],card=assertFound((await client.query("SELECT * FROM new_design.cards WHERE id=$1 AND space_id=$2 FOR UPDATE",[cardId,scope.spaceId])).rows[0],"资料不存在。");if(prior){await client.query("ROLLBACK");const saved=assertFound((await pool.query(`SELECT card.*,type.name card_type_name,version.version type_version FROM new_design.cards card JOIN new_design.card_types type ON type.id=card.card_type_id JOIN new_design.card_type_versions version ON version.id=card.type_version_id WHERE card.id=$1`,[cardId])).rows[0],"资料不存在。");return{id:String(prior.id),card:mapCard(saved),riskAccepted:false,createdAt:asDate(prior.created_at)};}if(card.status!=="archived")throw new NewDesignError("资料未归档，无需恢复。",409);if(Number(card.revision)!==input.expectedRevision)throw new NewDesignError("资料已被其他页面修改，请刷新后重试。",409);const result=await writeCardStatusVersion(client,card,"active",input.actor??ACTOR),eventId=randomUUID();await client.query(`INSERT INTO new_design.card_archive_events(id,space_id,book_id,card_id,from_status,to_status,from_revision,to_revision,risk_accepted,idempotency_key,created_by) VALUES($1,$2,$3,$4,'archived','active',$5,$6,false,$7,$8)`,[eventId,scope.spaceId,scope.bookId,cardId,input.expectedRevision,result.nextRevision,input.idempotencyKey,input.actor??ACTOR]);await client.query("COMMIT");const saved=assertFound((await pool.query(`SELECT card.*,type.name card_type_name,version.version type_version FROM new_design.cards card JOIN new_design.card_types type ON type.id=card.card_type_id JOIN new_design.card_type_versions version ON version.id=card.type_version_id WHERE card.id=$1`,[cardId])).rows[0],"恢复后资料不可读取。");return{id:eventId,card:mapCard(saved),riskAccepted:false,createdAt:new Date().toISOString()};}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}
